	(8, 8, 1, NULL, 'RONALD RAMIREZ', 1, 1, 'AV. LOS PARDOS 3301', '2026-05-28', 2, 1, 'APURIMAC', 'HUAQUIRCA', 'ANTABAMBA', 'EL PROYECTO DE MONITOREO DE CALIDAD AMBIENTAL DE LA CENTRAL HIDROELÉCTRICA CHAGLLA, SUBESTACIONES Y LÍNEAS DE  TRANSMISIÓN ASOCIADAS, SE ENCUENTRA UBICADO EN EL DISTRITO DE CHAGLLA, EN LA PROVINCIA DE PACHITEA,  DEPARTAMENTO DE HUÁNUCO. PARA LLEGAR A LAS ESTACIONES DE MONITOREO, SE TOMÓ LA VÍA HUÁNUCO, DONDE SE TRANSITA POR LA CARRETERA CENTRAL  HASTA LLEGAR AL PUENTE DEL DISTRITO DE CHINCHAVITO Y POSTERIORMENTE TOMAR LA NUEVA RUTA DE PUENTE CHINCHAVITO  A CAMPAMENTO CENTRAL DE HIDROELÉCTRICA CHAGLLA.', 'HUANUCO Y CERRO DE PASCO', 'PROYECTO DE MONITOREO DE CALIDAD AMBIENTAL DE LA CENTRAL HIDROELÉCTRICA CHAGLLA, SUBESTACIONES Y LÍNEAS DE  TRANSMISIÓN ASOCIADAS.', '2026-05-29', '2026-05-31', '[1, 2]', 'SERVICIO DE MONITOREO A TODO COSTO POPR GREENLAB', 'Adjunta en la la programación enviada', 'PROYECTO DE MONITOREO DE CALIDAD AMBIENTAL DE LA CENTRAL HIDROELÉCTRICA CHAGLLA, SUBESTACIONES Y LÍNEAS DE \nTRANSMISIÓN ASOCIADAS.', 'ANALISIS Y MONITOREO', 'A TODO COSTO POR GREENLAB', 'A TODO COSTO POR GREENLAB', '14 DIAS', 'CARRO DE GREENLAB', 'A TODO COSTO POR GREENLAB', 'A TODO COSTO POR GREENLAB', 'SI APLICA ENVIAR 2 GENERADORES ELECTRICOS', 2, 'INFORME DE MONITOREO AMBIENTAL', 'SUBIR A LA PLATAFORMA DE CHAGLLA', 'OS-2605-01', '--', '2026-05-29 17:44:06', '2026-05-29 22:44:06', NULL, NULL, NULL, NULL),
